const $=id=>document.getElementById(id),stage=$('stage'),status=$('status');let timer;
function toast(s){status.textContent=s;status.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>status.classList.remove('show'),3500);}
let project=freshProject();try{const saved=await readProject();if(saved)project=normalizeProject(saved);else{const raw=localStorage.getItem(EDITOR_KEY);if(raw)project=normalizeProject(JSON.parse(raw));}}catch{try{const raw=localStorage.getItem(EDITOR_KEY);if(raw)project=normalizeProject(JSON.parse(raw));}catch{}}
let model,selected='torso',helper,view='orbit',yaw=.55,pitch=.14,zoom=1,trace=false,points=[],refImage=null,refURL=null;
const history=[],future=[],refs=Object.fromEntries(['front','back','left','right'].map(k=>[k,{crop:[0,0,1,1],scale:1,x:0,y:0}]));
const labels={torso:'胸部全体',hips:'腰部全体',sternum:'胸部中央装甲',helmet:'頭部',back:'背部ユニット',pelvis:'骨盤',armL:'左腕 / 肩関節',armR:'右腕 / 肩関節',forearmL:'左前腕 / 肘関節',forearmR:'右前腕 / 肘関節',legL:'左脚 / 股関節',legR:'右脚 / 股関節',shinL:'左すね / 膝関節',shinR:'右すね / 膝関節',bootL:'左足',bootR:'右足',shoulderL:'左肩ユニット',shoulderR:'右肩ユニット',weaponL:'左武器',weaponR:'右武器'};
const scene=new T.Scene(),camera=new T.OrthographicCamera(-4,4,4,-4,.1,100);let renderer;
try{renderer=new T.WebGLRenderer({canvas:$('render'),alpha:true,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;}catch{toast('WebGLを起動できません。Safariで再読み込みしてください。');throw Error('WebGL unavailable');}
scene.add(new T.HemisphereLight(0xc4e5ff,0x43505b,2));for(const [x,y,z,color,intensity]of [[5,9,7,0xffecd4,3.5],[-5,4,-5,0x7faed9,3]]){const l=new T.DirectionalLight(color,intensity);l.position.set(x,y,z);scene.add(l);}
const grid=new T.GridHelper(14,28,0x456574,0x283e4a);scene.add(grid);
function projectSnapshot(){return {...project,transforms:structuredClone(project.transforms),plates:structuredClone(project.plates)};}
function snapshot(){history.push(projectSnapshot());if(history.length>20)history.shift();future.length=0;}
let saveChain=Promise.resolve();
function save(silent=false){const current=projectSnapshot();saveChain=saveChain.catch(()=>{}).then(async()=>{try{await writeProject(current);if(!current.reconstruction)localStorage.setItem(EDITOR_KEY,JSON.stringify(current));if(!silent)toast('機体を保存しました');}catch{try{localStorage.setItem(EDITOR_KEY,JSON.stringify(current));if(!silent)toast('機体を保存しました');}catch{toast('保存領域が不足しています。JSONで書き出してください');}}});return saveChain;}

function rebuild(){if(model){scene.remove(model.root);disposeModel(model.root);}model=makeEditorModel(project);scene.add(model.root);if(!model.nodes[selected])selected='torso';const select=$('part');select.replaceChildren();for(const key of Object.keys(model.nodes)){const option=document.createElement('option');option.value=key;option.textContent=labels[key]||key;select.append(option);}select.value=selected;const stats=modelStats(model.root);$('stats').textContent=`${Math.round(stats.triangles).toLocaleString()} TRI · ${stats.meshes} MESH`;$('model-name').textContent=project.name;refresh();resize();appearance();save(true);}
function transform(){return project.transforms[selected]||{position:[0,0,0],rotation:[0,0,0],scale:[1,1,1],visible:true};}
function refresh(){const v=transform();$('name').value=project.name;$('height').value=project.height;$('paint').value=project.paint;$('visible').checked=v.visible;for(const kind of ['position','rotation','scale'])for(let i=0;i<3;i++)$(`${kind}${i}`).value=v[kind][i];$('pose').value=0;applyTransforms(model.nodes,model.bases,project);highlight();}
for(const [kind,label,step,min,max]of [['position','位置 / m',.01,-10,10],['rotation','回転 / °',1,-180,180],['scale','寸法倍率',.01,.1,3]]){const h=document.createElement('h2');h.textContent=label;$('transform').append(h);const row=document.createElement('div');row.className='axes';for(let i=0;i<3;i++){const l=document.createElement('label');l.textContent=['X','Y','Z'][i];const input=document.createElement('input');Object.assign(input,{id:`${kind}${i}`,type:'number',step,min,max});input.addEventListener('change',()=>{snapshot();const v=structuredClone(transform());v[kind][i]=T.MathUtils.clamp(Number(input.value)||0,min,max);project.transforms[selected]=v;mirror();rebuild();});l.append(input);row.append(l);}$('transform').append(row);}
function mirror(){if(!$('mirror').checked||!/[LR]$/.test(selected))return;const other=selected.slice(0,-1)+(selected.endsWith('L')?'R':'L');if(!model.nodes[other])return;const v=structuredClone(project.transforms[selected]);v.position[0]*=-1;v.rotation[1]*=-1;v.rotation[2]*=-1;project.transforms[other]=v;}
function highlight(){if(helper){scene.remove(helper);helper.geometry.dispose();helper.material.dispose();}const node=model.nodes[selected];if(node&&node.visible){helper=new T.BoxHelper(node,0x83dafa);scene.add(helper);}else helper=null;}
function choose(key){if(!model.nodes[key])return;selected=key;$('part').value=key;refresh();toast(labels[key]||key);}
$('part').onchange=()=>choose($('part').value);
for(const id of ['name','height','paint'])$(id).onchange=()=>{snapshot();project[id]=id==='height'?T.MathUtils.clamp(Number($(id).value)||4.8,1,20):$(id).value;rebuild();};
$('visible').onchange=()=>{snapshot();project.transforms[selected]={...transform(),visible:$('visible').checked};mirror();rebuild();};
$('save').onclick=()=>save();$('resetPart').onclick=()=>{snapshot();delete project.transforms[selected];rebuild();};
$('undo').onclick=async()=>{if(history.length){future.push(projectSnapshot());project=history.pop();await prepareProjectionTexture(project);rebuild();}};
$('redo').onclick=async()=>{if(future.length){history.push(projectSnapshot());project=future.pop();await prepareProjectionTexture(project);rebuild();}};
$('reset').onclick=()=>{snapshot();project=freshProject();rebuild();toast('A-11初期状態へ戻しました。「戻す」で復元できます');};
$('pose').oninput=()=>{applyTransforms(model.nodes,model.bases,project);const a=T.MathUtils.degToRad(Number($('pose').value));for(const side of ['L','R']){model.nodes[`forearm${side}`].rotation.x-=a;model.nodes[`shin${side}`].rotation.x+=a*.7;}model.root.updateMatrixWorld(true);helper?.update();};
function appearance(){const wire=$('wire').checked,opacity=refImage&&view!=='orbit'?Number($('modelOpacity').value):1;model.root.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(m.isMeshStandardMaterial){m.wireframe=wire;m.transparent=opacity<1;m.opacity=opacity;m.depthWrite=opacity>=1;}}});}
function resize(){const w=stage.clientWidth,h=stage.clientHeight;if(!model||!w||!h)return;renderer.setSize(w,h,false);const span=project.height*1.35*zoom;camera.left=-span*w/h/2;camera.right=span*w/h/2;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();const target=new T.Vector3(0,project.height*.52,0);let direction=new T.Vector3(Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),Math.cos(yaw)*Math.cos(pitch));if(view==='front')direction.set(0,0,1);if(view==='back')direction.set(0,0,-1);if(view==='left')direction.set(-1,0,0);if(view==='right')direction.set(1,0,0);camera.position.copy(target).addScaledVector(direction,15);camera.lookAt(target);camera.updateMatrixWorld();drawRef();}
function setView(v){view=v;trace=false;points=[];$('hint').textContent='ドラッグで回転 · 2本指で拡大縮小 · 部品をタップ';$('trace').textContent='輪郭を描く';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(v!=='orbit'){$('refView').value=v;loadRefControls();}appearance();resize();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('zoomIn').onclick=()=>{zoom=Math.max(.4,zoom*.88);resize();};$('zoomOut').onclick=()=>{zoom=Math.min(2.5,zoom/ .88);resize();};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(c=>c.classList.toggle('active',b===c));document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==b.dataset.tab);});
const ray=new T.Raycaster(),gestures=new EditorGestures();
$('render').onpointerdown=e=>{e.preventDefault();$('render').setPointerCapture(e.pointerId);gestures.down(e.pointerId,e.clientX,e.clientY);};
$('render').onpointermove=e=>{const delta=gestures.move(e.pointerId,e.clientX,e.clientY);if(!delta||trace)return;if(delta.zoom!==1){zoom=T.MathUtils.clamp(zoom*delta.zoom,.4,2.5);resize();}else if(view==='orbit'&&(delta.dx||delta.dy)){yaw-=delta.dx*.009;pitch=T.MathUtils.clamp(pitch+delta.dy*.006,-.6,.6);resize();}};
$('render').onpointerup=e=>{if(!gestures.up(e.pointerId))return;const box=stage.getBoundingClientRect(),x=(e.clientX-box.left)/box.width,y=(e.clientY-box.top)/box.height;if(trace){points.push([x,y]);drawRef();return;}ray.setFromCamera(new T.Vector2(x*2-1,1-y*2),camera);const hits=ray.intersectObject(model.root,true);if(hits.length){let obj=hits[0].object;while(obj&&!Object.values(model.nodes).includes(obj))obj=obj.parent;const key=Object.entries(model.nodes).find(([,v])=>v===obj)?.[0];if(key)choose(key);}};
$('render').onpointercancel=e=>gestures.cancel(e.pointerId);$('render').onlostpointercapture=e=>gestures.cancel(e.pointerId);$('render').onwheel=e=>{e.preventDefault();zoom=T.MathUtils.clamp(zoom*Math.exp(e.deltaY*.001),.4,2.5);resize();};
new ResizeObserver(resize).observe(stage);
for(const [i,label]of ['切出X / %','切出Y / %','幅 / %','高さ / %'].entries()){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');Object.assign(input,{id:`crop${i}`,type:'number',min:0,max:100,step:.1});input.onchange=()=>{const r=refs[$('refView').value];r.crop[i]=T.MathUtils.clamp(Number(input.value)/100,i<2?0:.01,1);if(i<2)r.crop[i]=Math.min(r.crop[i],1-r.crop[i+2]);else r.crop[i]=Math.min(r.crop[i],1-r.crop[i-2]);loadRefControls();drawRef();};l.append(input);$('cropFields').append(l);}
function loadRefControls(){const r=refs[$('refView').value];r.crop.forEach((v,i)=>$(`crop${i}`).value=(v*100).toFixed(1));$('refScale').value=r.scale;$('refX').value=r.x;$('refY').value=r.y;}
$('refView').onchange=()=>setView($('refView').value);
for(const id of ['refScale','refX','refY'])$(id).onchange=()=>{const r=refs[$('refView').value];r.scale=T.MathUtils.clamp(Number($('refScale').value)||1,.2,3);r.x=Number($('refX').value)||0;r.y=Number($('refY').value)||0;drawRef();};
$('opacity').oninput=drawRef;$('modelOpacity').oninput=appearance;$('wire').onchange=appearance;
function preset(){const crops={front:[.024,.075,.247,.60],back:[.30,.075,.241,.60],left:[.56,.047,.191,.632],right:[.785,.054,.202,.626]};for(const key of Object.keys(refs))refs[key].crop=crops[key];loadRefControls();drawRef();}
$('presetCrop').onclick=preset;$('wholeCrop').onclick=()=>{refs[$('refView').value].crop=[0,0,1,1];loadRefControls();drawRef();};
$('imageFile').onchange=async()=>{const file=$('imageFile').files[0];if(!file)return;if(file.size>30*1024*1024){toast('30MB以下の画像を選んでください');return;}const url=URL.createObjectURL(file);try{await loadImage(url);if(refURL)URL.revokeObjectURL(refURL);refURL=url;toast('参考画像を読み込みました。切り出し範囲を合わせてください');}catch{URL.revokeObjectURL(url);toast('この画像を読み込めませんでした。PNGまたはJPEGを選んでください');}finally{$('imageFile').value='';}};
async function loadImage(url){const image=new Image();image.src=url;await image.decode();refImage=image;$('sheet').src=url;$('sheet').style.display='block';setView('front');drawRef();}
function drawRef(){const canvas=$('reference'),w=stage.clientWidth,h=stage.clientHeight;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;const c=canvas.getContext('2d');c.scale(devicePixelRatio,devicePixelRatio);c.clearRect(0,0,w,h);if(refImage&&view!=='orbit'){const r=refs[view],a=r.crop,sx=a[0]*refImage.width,sy=a[1]*refImage.height,sw=a[2]*refImage.width,sh=a[3]*refImage.height;const dh=h/1.35/zoom*r.scale,dw=dh*sw/sh;c.globalAlpha=Number($('opacity').value);c.drawImage(refImage,sx,sy,sw,sh,(w-dw)/2+r.x*w/100,(h-dh)/2+r.y*h/100,dw,dh);c.globalAlpha=1;}if(points.length){c.strokeStyle='#ffb264';c.fillStyle='#ffc987';c.lineWidth=2;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x*w,y*h):c.moveTo(x*w,y*h));c.stroke();for(const [x,y]of points){c.beginPath();c.arc(x*w,y*h,4,0,Math.PI*2);c.fill();}}}
$('trace').onclick=()=>{if(view!=='front')setView('front');trace=!trace;points=[];$('trace').textContent=trace?'描画を中止':'輪郭を描く';$('hint').textContent=trace?'装甲の外周を順にタップ → 装甲を作成':'ドラッグで回転 · 2本指で拡大縮小 · 部品をタップ';drawRef();};
$('traceUndo').onclick=()=>{points.pop();drawRef();};
$('makePlate').onclick=()=>{if(points.length<3){toast('外周を3点以上タップしてください');return;}if(project.plates.length>=100){toast('装甲は100個までです');return;}snapshot();applyTransforms(model.nodes,model.bases,project);model.root.updateMatrixWorld(true);const parent=model.nodes[selected],center=new T.Box3().setFromObject(parent).getCenter(new T.Vector3()),plane=new T.Plane(new T.Vector3(0,0,1),-center.z);const local=points.map(([x,y])=>{ray.setFromCamera(new T.Vector2(x*2-1,1-y*2),camera);const hit=ray.ray.intersectPlane(plane,new T.Vector3());return parent.worldToLocal(hit).toArray();});const centroid=local.reduce((a,p)=>a.map((v,i)=>v+p[i]/local.length),[0,0,0]);const id=`plate_${Date.now()}`;project.plates.push({id,parent:selected,points:local.map(p=>[p[0]-centroid[0],p[1]-centroid[1]]),depth:T.MathUtils.clamp(Number($('depth').value)||.12,.01,2),bevel:T.MathUtils.clamp(Number($('bevel').value)||0,0,.1),color:project.paint});project.transforms[id]={position:centroid,rotation:[0,0,0],scale:[1,1,1],visible:true};selected=id;trace=false;points=[];$('trace').textContent='輪郭を描く';rebuild();drawRef();toast('輪郭を立体装甲にしました。部品タブで位置・奥行きを調整できます');};
$('deletePlate').onclick=()=>{if(!project.plates.some(p=>p.id===selected)){toast('作成した装甲を選んでください');return;}snapshot();project.plates=project.plates.filter(p=>p.id!==selected);delete project.transforms[selected];selected='torso';rebuild();};
function download(blob,ext){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(project.name.replace(/[^\w\u3040-\u9fff-]+/g,'_')||'mech')+ext;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('ファイルを書き出しました');}
$('json').onclick=()=>download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),'.mech.json');
$('jsonFile').onchange=async()=>{try{const file=$('jsonFile').files[0];if(!file)return;if(file.size>24e6)throw Error('JSONは24MB以下を選んでください');const p=normalizeProject(JSON.parse(await file.text()));await prepareProjectionTexture(p);snapshot();project=p;rebuild();toast('機体を読み込みました');}catch(e){toast(e.message);}};
$('glb').onclick=async()=>{const button=$('glb');button.disabled=true;try{applyTransforms(model.nodes,model.bases,project);$('pose').value=0;model.root.updateMatrixWorld(true);const out=cleanExport(model.root);out.traverse(o=>{if(o.isMesh){o.material=o.material.clone();if(o.material.isMeshStandardMaterial){o.material.opacity=1;o.material.transparent=false;o.material.wireframe=false;o.material.depthWrite=true;}}});const data=await new GLTFExporter().parseAsync(out,{binary:true,trs:true,onlyVisible:true,maxTextureSize:1024});download(new Blob([data],{type:'model/gltf-binary'}),'.glb');}catch(e){toast('GLB出力失敗: '+e.message);}finally{button.disabled=false;}};
$('obj').onclick=()=>{applyTransforms(model.nodes,model.bases,project);$('pose').value=0;model.root.updateMatrixWorld(true);const lines=['# MECH FORGE: meters, Y up, +Z forward'],v=new T.Vector3(),n=new T.Vector3();let offset=1;model.root.traverseVisible(o=>{if(!o.isMesh)return;const g=o.geometry,p=g.attributes.position,norm=g.attributes.normal,matrix=new T.Matrix3().getNormalMatrix(o.matrixWorld);lines.push('o '+(o.parent.name||o.name||'armor'));for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld);lines.push(`v ${v.x} ${v.y} ${v.z}`);}for(let i=0;i<p.count;i++){n.fromBufferAttribute(norm,i).applyMatrix3(matrix).normalize();lines.push(`vn ${n.x} ${n.y} ${n.z}`);}const count=g.index?.count||p.count;for(let i=0;i<count;i+=3){const ids=[0,1,2].map(j=>(g.index?g.index.getX(i+j):i+j)+offset);lines.push('f '+ids.map(k=>`${k}//${k}`).join(' '));}offset+=p.count;});download(new Blob([lines.join('\n')],{type:'text/plain'}),'.obj');};
await prepareProjectionTexture(project).catch(()=>{});rebuild();loadRefControls();setView('orbit');toast('MECH FORGEを起動しました');
// Included reference is a local asset; imported photos never leave this browser.
loadImage('./assets/a11-reference.webp').then(()=>{preset();setView('orbit');}).catch(()=>{});
function frame(){if(!document.hidden){helper?.update();renderer.render(scene,camera);}requestAnimationFrame(frame);}frame();

$('autoGenerate').onclick=async()=>{
 if(!refImage){toast('参考画像を読み込んでください');return;}
 const button=$('autoGenerate');button.disabled=true;button.textContent='輪郭を解析・立体化しています…';
 $('autoReport').textContent='端末内で処理しています。高精細では数秒〜数十秒かかる場合があります。';
 try{
  const atlas=buildAtlas(); // Capture source textures before the worker yields to other edits.
  const images={};for(const key of $('autoLayout').value==='four'?['front','left','right','back']:['front']){
   const r=refs[key],a=r.crop,canvas=document.createElement('canvas');canvas.width=canvas.height=Number($('autoResolution').value)>=96?384:256;const c=canvas.getContext('2d',{willReadFrequently:true});
   const sw=Math.max(1,a[2]*refImage.width),sh=Math.max(1,a[3]*refImage.height);c.drawImage(refImage,a[0]*refImage.width,a[1]*refImage.height,sw,sh,0,0,canvas.width,canvas.height);
   const data=c.getImageData(0,0,canvas.width,canvas.height);images[key]={width:canvas.width,height:canvas.height,data:data.data,aspect:sw/sh};
  }
  const result=await new Promise((resolve,reject)=>{const worker=new Worker(new URL('./reconstruct-worker.js?v=2.4.2',import.meta.url),{type:'module'});const timeout=setTimeout(()=>{worker.terminate();reject(Error('処理時間が長すぎます。標準精度でもう一度生成してください'));},90000);const finish=()=>{clearTimeout(timeout);worker.terminate();};worker.onmessage=e=>{finish();e.data.ok?resolve(e.data.result):reject(Error(e.data.error));};worker.onerror=()=>{finish();reject(Error('画像解析を起動できません。ページを再読み込みしてください'));};worker.postMessage({images,options:{threshold:Number($('autoThreshold').value),resolution:Number($('autoResolution').value),relief:Number($('autoRelief').value),rounding:Number($('autoRounding').value)}});});
  result.atlas=atlas;await prepareProjectionTexture({reconstruction:result});snapshot();project.reconstruction=result;project.transforms={};project.plates=[];selected='torso';rebuild();setView('orbit');
  $('autoReport').textContent=`生成完了：${result.filled.toLocaleString()}個の体積セルから、${(result.triangleCount||result.faces?.length*2).toLocaleString()}三角形を生成。${result.views>1?'四面図の高さを合わせて連続した立体表面を生成':'一枚絵から奥行きを仮定'}。${result.fit?'輪郭一致度：'+Object.entries(result.fit).map(([key,value])=>({front:'正面',back:'背面',left:'左',right:'右'}[key])+value+'%').join(' / ')+'（抽出輪郭との投影比較）。':''}部品タブで補正し、出力タブからGLBを書き出せます。`;
  toast('画像から3Dモデルと装甲テクスチャを生成しました');
 }catch(e){$('autoReport').textContent=e.message;toast(e.message);}finally{button.disabled=false;button.textContent='画像を解析して3Dモデルを自動生成';}
};

$('autoLayout').onchange=()=>{if($('autoLayout').value==='single'){refs.front.crop=[0,0,1,1];setView('front');}else{preset();setView('front');}};

function buildAtlas(){const atlas=document.createElement('canvas');atlas.width=atlas.height=1024;const c=atlas.getContext('2d');c.fillStyle='#697077';c.fillRect(0,0,1024,1024);for(const [key,tx,ty]of [['front',0,0],['back',1,0],['left',0,1],['right',1,1]]){const a=refs[key].crop;c.drawImage(refImage,a[0]*refImage.width,a[1]*refImage.height,a[2]*refImage.width,a[3]*refImage.height,tx*512,ty*512,512,512);}return atlas.toDataURL('image/webp',.94);}
